<?php
require_once __DIR__ . '/config/bootstrap.php';
$categorySlug = trim((string)($_GET['kategori'] ?? ''));
$categories = $pdo->query('SELECT id, name, slug FROM project_categories ORDER BY name')->fetchAll();
$sql = "SELECT p.id, p.title, p.slug, p.summary, p.description, p.year, p.cover_image, c.name AS category, c.slug AS category_slug FROM projects p INNER JOIN project_categories c ON c.id = p.category_id WHERE p.status = 'published'";
$params = [];
if ($categorySlug !== '') { $sql .= ' AND c.slug = :slug'; $params['slug'] = $categorySlug; }
$sql .= ' ORDER BY p.published_at DESC, p.id DESC';
$stmt = $pdo->prepare($sql); $stmt->execute($params); $items = $stmt->fetchAll();
?>
